CREATE TABLE policies(policy_id INTEGER PRIMARY KEY, state VARCHAR NOT NULL, coverage VARCHAR NOT NULL, deductible INTEGER CHECK(deductible >= 0), coverage_limit INTEGER CHECK(coverage_limit > 0), effective TIMESTAMP, expiration TIMESTAMP, condition VARCHAR);
CREATE TABLE vendors(vendor_id INTEGER PRIMARY KEY, category VARCHAR, specialization VARCHAR, baseline_days DOUBLE, supplement_history DOUBLE);
CREATE TABLE adjusters(adjuster_id INTEGER PRIMARY KEY, team VARCHAR, experience VARCHAR, baseline_workload INTEGER);
CREATE TABLE claims(claim_id INTEGER PRIMARY KEY, policy_id INTEGER REFERENCES policies(policy_id), incident TIMESTAMP, fnol TIMESTAMP, claim_type VARCHAR, severity INTEGER CHECK(severity BETWEEN 1 AND 5), complexity INTEGER, initial_estimate BIGINT, current_reserve BIGINT, status VARCHAR, adjuster_id INTEGER REFERENCES adjusters(adjuster_id), vendor_id INTEGER REFERENCES vendors(vendor_id), settled TIMESTAMP, reopened TIMESTAMP, liability BOOLEAN);
CREATE TABLE events(event_id INTEGER PRIMARY KEY, claim_id INTEGER REFERENCES claims(claim_id), happened TIMESTAMP, kind VARCHAR, detail INTEGER, source VARCHAR);
CREATE TABLE payments(payment_id INTEGER PRIMARY KEY, claim_id INTEGER REFERENCES claims(claim_id), paid TIMESTAMP, amount BIGINT CHECK(amount >= 0), category VARCHAR, status VARCHAR, vendor_id INTEGER REFERENCES vendors(vendor_id), invoice VARCHAR, reverses INTEGER);
CREATE TABLE reserves(claim_id INTEGER REFERENCES claims(claim_id), changed TIMESTAMP, previous BIGINT CHECK(previous >= 0), new BIGINT CHECK(new >= 0), reason VARCHAR, PRIMARY KEY(claim_id, changed));
CREATE TABLE interventions(intervention_id INTEGER PRIMARY KEY, claim_id INTEGER REFERENCES claims(claim_id), kind VARCHAR, reviewed TIMESTAMP, expense_cents BIGINT, outcome VARCHAR, recovered_cents BIGINT);
